@@ -48,5 +48,11 @@ export async function sendInvite(input: InviteInput, deps: InviteDeps): Promise<ToolResult> {
   const sent = await deps.calendar.insert(input.event);
   if (!sent.ok) return fail("calendar", sent.error);

+  try {
+    await deps.db.insertActionLog({ tool: "calendar_invite", ref: sent.id, at: deps.now() });
+  } catch {
+    // best effort
+  }
+
   return ok({ id: sent.id, link: sent.htmlLink });
 }
